class KeywordHitMetric(BaseMetric):
    def __init__(self, required_keywords: list, threshold: float = {{threshold}}):
        self.threshold = threshold
        self.required_keywords = required_keywords
        self.evaluation_model = "keyword-checker"

    def measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        actual = (test_case.actual_output or "").lower()
        hits = []
        misses = []
        for kw in self.required_keywords:
            if kw.lower() in actual:
                hits.append(kw)
            else:
                misses.append(kw)
        total = len(self.required_keywords)
        self.score = round(len(hits) / total, 3) if total > 0 else 1.0
        self.success = self.score >= self.threshold
        if misses:
            self.reason = f"命中 {len(hits)}/{total} 个关键词，缺失: {misses}"
        else:
            self.reason = f"全部 {total} 个关键词命中"
        return self.score

    async def a_measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        return self.measure(test_case)

    def is_successful(self) -> bool:
        return bool(self.score and self.score >= self.threshold)

    @property
    def __name__(self):
        return "Keyword Hit Rate"
